using System;
using System.Linq;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class BlackoutTests
 {
  static void BindUi(GameState s,bool rendered=true)
  {FogUiHooks.Reset();GameManager.instance=new();GameManager.GameState=s;GameManager.Client=new(){GameState=s};GameManager.LocalPlayer=Native.Items(s.PlayerStates).Cast<PlayerState>().Single(p=>p.Id==2);MapRenderer.Current=new();if(rendered)MapRenderer.Current.RenderMap(s.Map);}
  static void UiCases()
  {
   Test("fog-ui-binds-safe-native-hooks",()=>{var h=new HarmonyLib.Harmony();NativeBlackoutUi.Install(h);Check(h.Hooks.Count==7&&h.Hooks.Contains("ClientInteraction.SelectTileInternal")&&h.Hooks.Contains("ClientInteraction.SelectUnit")&&!h.Hooks.Contains("ClientInteraction.SelectTile")&&h.Hooks.Contains("MapRenderer.RenderMap")&&h.Hooks.Contains("MapRenderer.Clear")&&h.Hooks.Contains("MapRenderer.OnDestroy"),"selection sinks remain guarded; native fog input dispatcher remains installed by the game; renderer lifecycle observed");});
   Test("fog-ui-refreshes-only-on-mask-or-viewer-change",()=>{var s=Make();BindUi(s);NativeBlackoutUi.Tick();Check(!MapRenderer.Current!.shouldRefresh,"initial native render is already current");MapRenderer.Current.shouldRefresh=false;NativeBlackoutUi.Tick();Check(!MapRenderer.Current.shouldRefresh,"idle tick does not rerender");Cast(s,2,1);NativeBlackoutUi.Tick();Check(MapRenderer.Current.shouldRefresh,"cast uses normal native map refresh");MapRenderer.Current.shouldRefresh=false;var old=NativeGameStateEnvelope.Get(s)!;NativeGameStateEnvelope.Set(s,old.Revision+1,NativeIdentityLedgerCodec.Encode(Read(s),old.Revision+1));NativeBlackoutUi.Tick();Check(!MapRenderer.Current.shouldRefresh,"unrelated ledger revision does not refresh unchanged fog");});
   foreach(bool unit in new[]{true,false})Test("fog-ui-clears-stale-"+(unit?"unit":"city")+"-selection",()=>{var s=Make();BindUi(s);var underlying=Add(s,20,2,1,2);var interaction=new ClientInteraction();var u=new Unit{UnitState=underlying};var t=new Tile{Data=Tile(s,2,1)};if(unit)interaction.selectedUnit=u;else interaction.selectedTile=t;Cast(s,2,1);NativeBlackoutUi.AfterRefresh(interaction);Check(interaction.Clears==1&&interaction.selectedUnit is null&&interaction.selectedTile is null,"old selection cleared after native fog refresh");Check(!NativeBlackoutUi.BeforeUnit(u)&&!NativeBlackoutUi.BeforeTile(t),"map and cycle re-selection denied while covered");GameManager.LocalPlayer=Native.Items(s.PlayerStates).Cast<PlayerState>().First();Check(NativeBlackoutUi.BeforeUnit(u)&&NativeBlackoutUi.BeforeTile(t),"caster's ordinary selection unaffected");});
   foreach(string contents in new[]{"empty","own-unit","enemy-unit","city"})Test("fog-click-native-feedback-"+contents,()=>{
    var s=Make();BindUi(s);var data=Tile(s,2,1);if(contents.EndsWith("unit",StringComparison.Ordinal))Add(s,20,2,1,contents=="own-unit"?(byte)2:(byte)1);
    if(contents=="city")data.improvement=new(){type=Polytopia.Data.ImprovementData.Type.city};Cast(s,2,1);
    var original=NativeGameStateEnvelope.Get(s)!;var explorers=data.explorers;var queue=s.ActionStack;var tile=new global::Tile{Data=data};var interaction=new ClientInteraction();
    interaction.OnPress(tile);interaction.OnRelease(tile,0);
    Check(tile.Presses==1&&tile.Releases==1&&!tile.FogPressed&&tile.Puffs==1,"normal fog press, release and cloud puff");
    Check(AudioManager.Played.Count==1&&AudioManager.Played[0].Sound==AudioUtils.GetCloudForCoordinate(tile.Coordinates)&&AudioManager.Played[0].At.X==2&&AudioManager.Played[0].At.Y==1,"same coordinate-selected native cloud SFX");
    Check(interaction.Clears==1&&interaction.selectedUnit is null&&interaction.selectedTile is null&&interaction.AcceptedMoves==0,"fog click reveals no unit/city controls or commands");
    Check(ReferenceEquals(original,NativeGameStateEnvelope.Get(s))&&ReferenceEquals(explorers,data.explorers)&&ReferenceEquals(queue,s.ActionStack)&&!data.GetExplored(2),"fog feedback changes no authoritative state or exploration");
   });
   Test("fog-click-repeat-has-native-feedback-each-click",()=>{var s=Make();BindUi(s);Cast(s,2,1);var tile=new global::Tile{Data=Tile(s,2,1)};var interaction=new ClientInteraction();interaction.OnRelease(tile,0);interaction.OnRelease(tile,0);Check(tile.Puffs==2&&AudioManager.Played.Count==2&&interaction.Clears==2,"ordinary native repeated fog clicks are not swallowed or custom-deduplicated");});
   Test("fog-click-caster-normal-visible-selection",()=>{var s=Make();BindUi(s);Cast(s,2,1);GameManager.LocalPlayer=Native.Items(s.PlayerStates).Cast<PlayerState>().First();var tile=new global::Tile{Data=Tile(s,2,1)};var interaction=new ClientInteraction();interaction.OnRelease(tile,0);Check(ReferenceEquals(interaction.selectedTile,tile)&&tile.Puffs==0&&AudioManager.Played.Count==0,"caster's visible tile still uses native selection");});
   Test("fog-click-ordinary-unexplored-tile-without-blackout",()=>{var s=Make();BindUi(s);var data=Tile(s,2,1);data.SetExplored(2,false);var tile=new global::Tile{Data=data};var interaction=new ClientInteraction();interaction.OnPress(tile);interaction.OnRelease(tile,0);Check(tile.Puffs==1&&AudioManager.Played.Count==1&&interaction.selectedTile is null,"native explorer flags alone drive fog response");});
   Test("fog-click-unbound-state-uses-native-explorer-flags",()=>{var s=Make();BindUi(s);NativeGameStateEnvelope.Values.Clear();NativeBlackout.Clear();var data=Tile(s,2,1);data.explorers!.Remove(2);var tile=new global::Tile{Data=data};var interaction=new ClientInteraction();interaction.OnRelease(tile,0);Check(tile.Puffs==1&&AudioManager.Played.Count==1&&interaction.selectedTile is null,"unbound preview/replay state retains native fog behavior");});
   Test("fog-click-replay-fog-disabled-remains-native",()=>{var s=Make();BindUi(s);NativeGameStateEnvelope.Values.Clear();NativeBlackout.Clear();GameManager.ReplayFogDisabled=true;var tile=new global::Tile{Data=Tile(s,2,1)};tile.Data.explorers!.Remove(2);var interaction=new ClientInteraction();interaction.OnRelease(tile,0);Check(tile.Puffs==0&&AudioManager.Played.Count==0&&ReferenceEquals(interaction.selectedTile,tile),"replay native fog preference is not overwritten");});
   Test("fog-click-ordinary-move-into-fog-remains-native",()=>{var s=Make();BindUi(s);Cast(s,2,1);var source=Add(s,20,3,1,2);var interaction=new ClientInteraction{selectedUnit=new(){UnitState=source,CanMoveIntoFog=true}};interaction.OnRelease(new(){Data=Tile(s,2,1)},0);Check(interaction.MoveAttempts==1&&interaction.AcceptedMoves==1&&AudioManager.Played.Count==0,"native legal movement dispatch is not swallowed by target Blackout");Check(!Tile(s,2,1).GetExplored(2),"input dispatch grants no exploration itself");});
   Test("fog-click-stale-covered-source-command-still-denied",()=>{var s=Make();BindUi(s);var source=Add(s,20,2,1,2);Cast(s,2,1);var interaction=new ClientInteraction{selectedUnit=new(){UnitState=source,CanMoveIntoFog=true}};interaction.OnRelease(new(){Data=Tile(s,3,1)},0);Check(interaction.MoveAttempts==1&&interaction.AcceptedMoves==0,"final authoritative source guard still vetoes stale selected unit");NativeBlackoutUi.AfterRefresh(interaction);Check(interaction.selectedUnit is null,"native refresh retires stale covered selection");});
   Test("fog-click-direct-hidden-selection-sinks-still-denied",()=>{var s=Make();BindUi(s);var source=Add(s,20,2,1,2);Cast(s,2,1);var interaction=new ClientInteraction();interaction.SelectTileInternal(new(){Data=Tile(s,2,1)});interaction.SelectUnit(new(){UnitState=source});Check(interaction.selectedTile is null&&interaction.selectedUnit is null&&AudioManager.Played.Count==0,"programmatic selection/cycling cannot bypass fog by avoiding click dispatcher");});
   Test("fog-click-null-selection-clear-remains-native",()=>{var s=Make();BindUi(s);var interaction=new ClientInteraction{selectedTile=new(){Data=Tile(s,2,1)},selectedUnit=new(){UnitState=Tile(s,1,1).unit!}};interaction.SelectTileInternal(null);interaction.SelectUnit(null);Check(interaction.selectedTile is null&&interaction.selectedUnit is null,"null is a valid native deselection, not a covered tile read");});
   Test("fog-click-rediscovery-restores-ordinary-selection",()=>{var s=Make();BindUi(s);Cast(s,2,1);s.CurrentPlayer=2;Add(s,20,2,2,2);var p=GameManager.LocalPlayer!;RefreshSource(s,new MoveAction{PlayerId=2,UnitId=20},()=>ActionUtils.ExploreFromTile(s,p,Tile(s,2,2),2,true));Execute(s,Pending(s,2,2,1));var tile=new global::Tile{Data=Tile(s,2,1)};var interaction=new ClientInteraction();interaction.OnRelease(tile,0);Check(ReferenceEquals(interaction.selectedTile,tile)&&AudioManager.Played.Count==0,"legitimate discovery restores native tile selection rather than permanent fog behavior");});
   Test("fog-ui-teardown-keeps-new-match-independent",()=>{var s=Make();BindUi(s);Cast(s,2,1);NativeBlackoutUi.Tick();GameManager.instance=null;NativeBlackoutUi.Tick();var other=Make();BindUi(other);var tile=new Tile{Data=Tile(other,2,1)};Check(NativeBlackoutUi.BeforeTile(tile),"retired match does not hide fresh tile");NativeBlackoutUi.Tick();Check(!MapRenderer.Current!.shouldRefresh,"new native map render does not request a redundant refresh");});
   UiLifecycleCases();
  }
 }
}
